def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    last_my, last_op = history[-1]

    if op_c == 0:
        return 'D'

    if op_d <= max(1, n // 8):
        if last_my == 'D' and last_op == 'D':
            dd = 0
            for i in range(n-1, -1, -1):
                if history[i][0] == 'D' and history[i][1] == 'D':
                    dd += 1
                else:
                    break
            if dd >= 2 and rng.random() < 0.3:
                return 'C'
        return 'C'

    if op_d * 2 >= n:
        return 'D'

    if last_op == 'C' and op_d <= n // 3:
        return 'C'

    if last_op == 'D':
        if last_my == 'D':
            dd = 0
            for i in range(n-1, -1, -1):
                if history[i][0] == 'D' and history[i][1] == 'D':
                    dd += 1
                else:
                    break
            if dd >= 3 and op_c > n * 0.2:
                if rng.random() < 0.25:
                    return 'C'
            return 'D'
        else:
            if op_c > n * 0.7 and n > 20:
                if rng.random() < 0.15:
                    return 'C'
            return 'D'

    if op_d * 3 > n:
        return 'D'

    return 'C'
